arguments.command:
set -e
# Add custom log format + rate limit zone to nginx.conf (inside http block)
grep -q 'benchmark_format' /etc/nginx/nginx.conf || sed -i '/http {/a\
\tlog_format benchmark_format '"'"'$time_local $request_method $status "$http_user_agent"'"'"';\
\tlimit_req_zone $binary_remote_addr zone=benchmark_limit:10m rate=10r/s;' /etc/nginx/nginx.conf

# Server config
cat > /etc/nginx/conf.d/benchmark-site.conf <<'EOF'
server {
    listen 8080;
    server_name localhost;

    root /var/www/html;
    index index.html;

    access_log /var/log/nginx/benchmark-access.log benchmark_format;
    error_log /var/log/nginx/benchmark-error.log;

    limit_req zone=benchmark_limit burst=10;

    error_page 404 /404.html;

    location / {
        try_files $uri $uri/ =404;
    }

    location = /404.html {
        internal;
    }
}
EOF

# Disable default site
rm -f /etc/nginx/sites-enabled/default

# Document root + content
mkdir -p /var/www/html
echo "Welcome to the benchmark webserver" > /var/www/html/index.html
echo "Page not found - Please check your URL" > /var/www/html/404.html

# Test config
nginx -t

